# Bám sách: trang 60–61 + đáp án + Mini dictionary unit 28. Không chép nguyên văn.
theory = (
 H("A", "Describing problems", "Mô tả vấn đề")
 + P("Kate tells her friend Rosie about the problems in her family.", "Kate kể với bạn là Rosie về những rắc rối trong gia đình mình.")
 + T([
    ("<b>hang over</b>", "Possible job cuts at work make her worry about what will happen.", "Nguy cơ cắt giảm nhân sự ở công ty khiến cô lo lắng."),
    ("<b>botch up</b>", "(informal) Senior managers did their job badly and lost the company millions.", "(thân mật) Ban lãnh đạo làm hỏng việc, khiến công ty mất hàng triệu bảng."),
    ("<b>break down</b> / <b>spill over</b>", "Her daughter’s long relationship failed because work pressures started to affect their private lives.", "Mối quan hệ lâu năm của con gái cô đổ vỡ vì áp lực công việc lan sang đời sống riêng."),
    ("<b>be caught up in</b> / <b>run into</b>", "Her son, a journalist, got involved in a revolution abroad and began to have difficulties leaving.", "Con trai cô, một nhà báo, bị cuốn vào một cuộc cách mạng ở nước ngoài và gặp khó khăn khi rời đi."),
    ("<b>land in</b>", "He even ended up in prison for a few days.", "Anh thậm chí phải vào tù vài ngày."),
    ("<b>bear up</b> / <b>be riddled with</b>", "Rosie asks how Kate is coping bravely; Rosie herself is worried because a relative is seriously ill.", "Rosie hỏi Kate có gắng gượng nổi không; chính Rosie cũng lo vì một người thân bệnh nặng."),
 ])
 + H("B", "Dealing with problems", "Giải quyết vấn đề")
 + P("A therapist who writes an advice column gives general advice.", "Một nhà trị liệu phụ trách chuyên mục tư vấn đưa ra lời khuyên chung.")
 + T([
    ("<b>resign yourself to</b> / <b>safeguard against</b>", "Accept that problems will come; you cannot protect yourself from every bad event.", "Chấp nhận rằng rắc rối sẽ đến; không thể phòng tránh mọi điều xấu."),
    ("<b>walk away</b> / <b>live with</b>", "You cannot leave every hard situation; you must accept some and carry on.", "Không thể bỏ chạy khỏi mọi tình huống khó; phải chấp nhận mà sống tiếp."),
    ("<b>iron out</b> / <b>fall back on</b>", "Find ways to solve difficulties; do not be too proud to turn to your parents for advice.", "Tìm cách tháo gỡ khó khăn; đừng ngại nhờ bố mẹ khuyên bảo."),
    ("<b>smooth over</b> / <b>clear up</b>", "Talking can make a disagreement less serious; explaining your feelings may sort out a misunderstanding (see Unit 23).", "Nói chuyện giúp làm dịu bất đồng; giải thích cảm xúc có thể gỡ hiểu lầm (xem bài 23)."),
    ("<b>make up for</b>", "If you behaved badly, apologise and do something good to repair it.", "Nếu cư xử tệ, hãy xin lỗi và làm điều tốt để bù lại."),
    ("<b>resort to</b> / <b>grasp at</b>", "Do not turn to wrong behaviour or seize the first easy way out just because you are unhappy.", "Đừng tìm đến hành vi sai trái hay vội nắm lấy lối thoát dễ dàng đầu tiên chỉ vì đang bất mãn."),
 ])
 + NOTE("<b>Exercise 28.2 – rewrite with a phrasal verb</b>: a body full of disease → <b>riddled with</b> disease; quickly took the first chance → <b>grasped at</b>; used my old map-reading skills → <b>fell back on</b> / <b>resorted to</b>; did things the wrong way → <b>botched</b> things <b>up</b>; protect yourself from heart disease → <b>safeguard against</b>; be brave and carry on → <b>bear up</b>; reluctantly accept → <b>resign ourselves to</b>; resolve misunderstandings → <b>clear up</b> / <b>iron out</b>.",
        "<b>Bài 28.2 – viết lại bằng phrasal verb</b>: cơ thể đầy bệnh tật → <b>riddled with</b> disease; vội nắm lấy cơ hội đầu tiên → <b>grasped at</b>; dùng lại kỹ năng đọc bản đồ → <b>fell back on</b> / <b>resorted to</b>; làm hỏng việc → <b>botched</b> things <b>up</b>; phòng bệnh tim → <b>safeguard against</b>; gắng gượng sống tiếp → <b>bear up</b>; miễn cưỡng chấp nhận → <b>resign ourselves to</b>; gỡ hiểu lầm → <b>clear up</b> / <b>iron out</b>.")
)
